-- ============================================================================
-- AgriTabang — 06: fully filled RSBSA forms + RSBSA numbers + President notices
-- Run AFTER 01 and 04. Touches ONLY farmer1..farmer92@agritabang.ph. Safe to run twice.
--   * RSBSA number for every farmer (sample format 10-13-15-001-0000NN, NOT issued by DA)
--   * Transaction code (PCN and TRN) and every field of the RSBSA Enrollment Form filled in
--     (sample data: sex Male to match the shared photo, married, same sample mother/spouse names...)
--   * profile photo re-saved at 300 x 300 so the 2x2 print is sharp
--   * Farmer 38 joins LARFA so all 5 applicants are association members (the President counts members)
--   * the President gets notices for the P5,000 announcement and the 5 applications
-- Boxes that do not apply (a 2nd/3rd parcel, extra crop rows, extension name) stay empty on purpose.
-- ============================================================================
begin;
do $$ begin execute 'alter table public.farmers disable trigger trg_notify_president_membership';
exception when undefined_object then null; end $$;

update public.farmers f set photo_url = 'data:image/jpeg;base64,'
  from public.profiles p where p.id = f.id and p.email ~ '^farmer[0-9]+@agritabang\.ph$';

update public.farmers f set is_association_member = true,
       association_id = (select id from public.associations where name = 'LARFA')
  from public.profiles p where p.id = f.id and p.email = 'farmer38@agritabang.ph';

