-- President notices (skipped if the same notice already exists)
insert into public.notifications (recipient_id, icon, message, category)
select pr.id, 'fa-hand-holding-dollar',
       'The MAO posted <b>Cash Assistance:</b> ₱5,000 Cash Assistance for Corn and Cassava Farmers.', 'assistance_post'
  from public.profiles pr
 where pr.role = 'president'
   and exists (select 1 from public.assistance_announcements a where a.title = '₱5,000 Cash Assistance for Corn and Cassava Farmers')
   and not exists (select 1 from public.notifications n where n.recipient_id = pr.id and n.category = 'assistance_post'
                   and n.message like '%5,000 Cash Assistance for Corn and Cassava%');

insert into public.notifications (recipient_id, icon, message, category)
select pr.id, 'fa-file-circle-plus',
       '<b>' || fp.full_name || '</b> applied for <b>₱5,000 Cash Assistance for Corn and Cassava Farmers</b>.', 'application'
  from public.profiles pr
 cross join public.profiles fp
 where pr.role = 'president'
   and fp.email in ('farmer1@agritabang.ph','farmer6@agritabang.ph','farmer27@agritabang.ph','farmer38@agritabang.ph','farmer53@agritabang.ph')
   and not exists (select 1 from public.notifications n where n.recipient_id = pr.id and n.category = 'application'
                   and n.message like '%' || fp.full_name || '%applied for%');

do $$ begin execute 'alter table public.farmers enable trigger trg_notify_president_membership';
exception when undefined_object then null; end $$;
commit;
